"""Tests for inline formatting: bold, italic and code spans."""

from mdlite import to_html


def test_bold_in_paragraph():
    assert to_html("**bold**") == "<p><strong>bold</strong></p>"


def test_italic_in_paragraph():
    assert to_html("*italic*") == "<p><em>italic</em></p>"


def test_bold_in_heading():
    assert to_html("# **B**") == "<h1><strong>B</strong></h1>"


def test_italic_in_heading():
    assert to_html("## *i*") == "<h2><em>i</em></h2>"


def test_code_span():
    assert to_html("`code`") == "<p><code>code</code></p>"


def test_code_span_escapes_content():
    assert to_html("`a < b > c & d`") == (
        "<p><code>a &lt; b &gt; c &amp; d</code></p>"
    )


def test_no_formatting_inside_code_span():
    assert to_html("`*not* bold`") == "<p><code>*not* bold</code></p>"


def test_code_span_in_heading():
    assert to_html("# `x`") == "<h1><code>x</code></h1>"


def test_bold_and_italic_together():
    assert to_html("*a* and **b**") == (
        "<p><em>a</em> and <strong>b</strong></p>"
    )


def test_nested_emphasis():
    assert to_html("**bold *it* bold**") == (
        "<p><strong>bold <em>it</em> bold</strong></p>"
    )


def test_markers_flanked_by_spaces_stay_literal():
    # The documented example: opening/closing '*' next to spaces.
    assert to_html("2 * 3 * 4") == "<p>2 * 3 * 4</p>"


def test_unpaired_opening_marker_is_literal():
    assert to_html("*a") == "<p>*a</p>"


def test_unpaired_closing_marker_is_literal():
    assert to_html("a *") == "<p>a *</p>"


def test_unpaired_bold_is_literal():
    assert to_html("a ** b") == "<p>a ** b</p>"


def test_emphasis_escapes_its_content():
    assert to_html("**a & b**") == "<p><strong>a &amp; b</strong></p>"


def test_multiple_code_spans():
    assert to_html("`a` and `b`") == (
        "<p><code>a</code> and <code>b</code></p>"
    )


def test_unpaired_backtick_is_literal():
    assert to_html("a ` b") == "<p>a ` b</p>"

"""Tests for list blocks: unordered and ordered items."""

from mdlite import to_html


def test_documented_unordered_example():
    assert to_html("- a\n- b") == "<ul>\n<li>a</li>\n<li>b</li>\n</ul>"


def test_documented_ordered_example():
    assert to_html("1. a\n2. b") == "<ol>\n<li>a</li>\n<li>b</li>\n</ol>"


def test_star_bullet_items_are_unordered():
    assert to_html("* a\n* b") == "<ul>\n<li>a</li>\n<li>b</li>\n</ul>"


def test_multi_digit_ordered_items():
    assert to_html("10. a\n11. b") == "<ol>\n<li>a</li>\n<li>b</li>\n</ol>"


def test_single_item_lists():
    assert to_html("- a") == "<ul>\n<li>a</li>\n</ul>"
    assert to_html("1. a") == "<ol>\n<li>a</li>\n</ol>"


def test_inline_formatting_inside_items():
    assert to_html("- **b** and *i*") == (
        "<ul>\n<li><strong>b</strong> and <em>i</em></li>\n</ul>"
    )


def test_code_span_inside_item():
    assert to_html("- `x`") == "<ul>\n<li><code>x</code></li>\n</ul>"


def test_item_text_is_escaped():
    assert to_html("- a & b < c") == "<ul>\n<li>a &amp; b &lt; c</li>\n</ul>"


def test_item_line_ends_preceding_paragraph():
    assert to_html("para\n- a") == "<p>para</p>\n<ul>\n<li>a</li>\n</ul>"


def test_list_after_paragraph_with_blank_line():
    assert to_html("p\n\n- a") == "<p>p</p>\n<ul>\n<li>a</li>\n</ul>"


def test_heading_after_list():
    assert to_html("- a\n# H") == "<ul>\n<li>a</li>\n</ul>\n<h1>H</h1>"


def test_mixed_kinds_split_into_separate_lists():
    assert to_html("- a\n1. b") == (
        "<ul>\n<li>a</li>\n</ul>\n<ol>\n<li>b</li>\n</ol>"
    )


def test_mixed_kinds_reversed():
    assert to_html("1. a\n- b") == (
        "<ol>\n<li>a</li>\n</ol>\n<ul>\n<li>b</li>\n</ul>"
    )


def test_blank_line_splits_list():
    assert to_html("- a\n\n- b") == (
        "<ul>\n<li>a</li>\n</ul>\n<ul>\n<li>b</li>\n</ul>"
    )


def test_non_item_line_starts_paragraph_after_list():
    assert to_html("- a\nb") == "<ul>\n<li>a</li>\n</ul>\n<p>b</p>"


def test_paragraph_between_lists():
    assert to_html("- a\n\np\n\n- b") == (
        "<ul>\n<li>a</li>\n</ul>\n<p>p</p>\n<ul>\n<li>b</li>\n</ul>"
    )


def test_dash_without_space_is_a_paragraph():
    assert to_html("-a") == "<p>-a</p>"


def test_number_lines_without_dot_and_space_are_paragraphs():
    assert to_html("1.a") == "<p>1.a</p>"
    assert to_html("1 a") == "<p>1 a</p>"
    assert to_html("1.") == "<p>1.</p>"


def test_empty_item():
    assert to_html("- ") == "<ul>\n<li></li>\n</ul>"

"""Tests for fenced code blocks."""

from mdlite import to_html


def test_basic_code_block():
    assert to_html("```\ncode\n```") == "<pre><code>code</code></pre>"


def test_code_block_with_language():
    assert to_html("```python\nx = 1\n```") == (
        '<pre><code class="language-python">x = 1</code></pre>'
    )


def test_multiline_block_keeps_lines():
    assert to_html("```\na\nb\n```") == "<pre><code>a\nb</code></pre>"


def test_blank_lines_inside_block_are_kept():
    assert to_html("```\na\n\nb\n```") == "<pre><code>a\n\nb</code></pre>"


def test_content_is_escaped_but_not_formatted():
    assert to_html("```\n**b** & <x>\n```") == (
        "<pre><code>**b** &amp; &lt;x&gt;</code></pre>"
    )


def test_indentation_is_kept():
    assert to_html("```\n    indented\n```") == (
        "<pre><code>    indented</code></pre>"
    )


def test_unclosed_block_runs_to_end_of_input():
    assert to_html("```\ncode") == "<pre><code>code</code></pre>"


def test_unclosed_block_with_language():
    assert to_html("```py\ncode") == '<pre><code class="language-py">code</code></pre>'


def test_only_an_exact_fence_closes():
    # A '```python' line inside the block is content, not a closing fence.
    assert to_html("```\n```python\n```") == "<pre><code>```python</code></pre>"


def test_block_between_paragraphs():
    assert to_html("before\n```\nc\n```\nafter") == (
        "<p>before</p>\n<pre><code>c</code></pre>\n<p>after</p>"
    )


def test_block_after_list():
    assert to_html("- a\n```\nc\n```") == (
        "<ul>\n<li>a</li>\n</ul>\n<pre><code>c</code></pre>"
    )


def test_block_after_heading():
    assert to_html("# H\n```\nc\n```") == "<h1>H</h1>\n<pre><code>c</code></pre>"


def test_block_at_start_of_input():
    assert to_html("```\nc\n```\nend") == "<pre><code>c</code></pre>\n<p>end</p>"


def test_heading_and_list_lines_inside_block_are_literal():
    assert to_html("```\n# not a heading\n- not an item\n```") == (
        "<pre><code># not a heading\n- not an item</code></pre>"
    )


def test_empty_block():
    assert to_html("```\n```") == "<pre><code></code></pre>"

"""Tests for inline links: [text](url) -> <a href="url">text</a>."""

from mdlite import to_html


def test_basic_link():
    assert to_html("[text](url)") == '<p><a href="url">text</a></p>'


def test_link_among_other_words():
    assert to_html("see [a](u) now") == '<p>see <a href="u">a</a> now</p>'


def test_two_links_in_one_paragraph():
    assert to_html("[a](u) and [b](v)") == (
        '<p><a href="u">a</a> and <a href="v">b</a></p>'
    )


def test_bold_inside_link_text():
    assert to_html("[**b**](u)") == '<p><a href="u"><strong>b</strong></a></p>'


def test_italic_inside_link_text():
    assert to_html("[*b*](u)") == '<p><a href="u"><em>b</em></a></p>'


def test_mixed_formatting_inside_link_text():
    assert to_html("[**a** and *b*](u)") == (
        '<p><a href="u"><strong>a</strong> and <em>b</em></a></p>'
    )


def test_code_span_inside_link_text():
    assert to_html("[a `b` c](u)") == '<p><a href="u">a <code>b</code> c</a></p>'


def test_link_inside_bold():
    assert to_html("**[a](u)**") == '<p><strong><a href="u">a</a></strong></p>'


def test_link_in_heading():
    assert to_html("# [a](u)") == '<h1><a href="u">a</a></h1>'


def test_link_in_list_item():
    assert to_html("- [a](u)") == '<ul>\n<li><a href="u">a</a></li>\n</ul>'


def test_ampersand_escaped_in_url():
    assert to_html("[a](u?x=1&y=2)") == '<p><a href="u?x=&amp;y=2">a</a></p>'


def test_double_quote_escaped_in_url():
    assert to_html('[a]("b")') == '<p><a href="&quot;b&quot;">a</a></p>'


def test_link_syntax_in_code_span_stays_literal():
    assert to_html("`[a](b)`") == "<p><code>[a](b)</code></p>"


def test_unclosed_url_stays_literal():
    assert to_html("[a](u") == "<p>[a](u</p>"


def test_space_before_paren_stays_literal():
    assert to_html("[a] (u)") == "<p>[a] (u)</p>"


def test_empty_url_stays_literal():
    assert to_html("[a]()") == "<p>[a]()</p>"


def test_plain_brackets_stay_literal():
    assert to_html("[a]") == "<p>[a]</p>"
